function build(id, raw) {
  const { w, h } = raw, half = h / 2;
  if (h % 2) throw new Error(`map ${id}: height must be even`);
  const top = Array.from({ length: half }, () => Array(w).fill(raw.fill || '.'));
  if (raw.border) {
    for (let x = 0; x < w; x++) top[0][x] = raw.border;
    for (let y = 0; y < half; y++) { top[y][0] = raw.border; top[y][w - 1] = raw.border; }
  }
  for (const [ch, x, y, ow, oh] of raw.ops) {
    for (let j = y; j < y + oh; j++) for (let i = x; i < x + ow; i++) {
      if (j < 0 || j >= half || i < 0 || i >= w) throw new Error(`map ${id}: op ${ch} ${x},${y} leaves the north half`);
      top[j][i] = ch;
    }
  }
  raw.spawns.forEach(([x, y], s) => { top[y][x] = 'ABC'[s]; });
  for (const [x, y] of raw.itemSpots) top[y][x] = '*';
  const flip = (c) => (c === 'A' ? 'a' : c === 'B' ? 'b' : c === 'C' ? 'c' : c);
  const topRows = top.map((r) => r.join(''));
  const rows = topRows.concat(topRows.slice().reverse().map((r) => [...r].reverse().map(flip).join('')));
  const tiles = new Uint8Array(w * h); // tiles[ty * w + tx], ty = 0 is the SOUTH edge
  const spawns = [[], []];
  const itemSpawns = [];
  const pads = [];
  for (let r = 0; r < h; r++) {
    const ty = h - 1 - r;
    for (let tx = 0; tx < w; tx++) {
      let ch = rows[r][tx];
      const cx = (tx + 0.5) * TILE, cy = (ty + 0.5) * TILE;
      const si = 'ABCabc'.indexOf(ch);
      if (si >= 0) { spawns[si < 3 ? 0 : 1][si % 3] = { x: cx, y: cy }; ch = '.'; }
      else if (ch === '*') { itemSpawns.push({ x: cx, y: cy, tx, ty }); ch = '.'; }
      const tid = CH2TILE[ch];
      if (!tid) throw new Error(`map ${id}: unknown tile "${ch}"`);
      tiles[ty * w + tx] = TILE_CODE[tid];
      if (tid === 'pad') pads.push({ x: cx, y: cy, tx, ty });
    }
  }
  for (const t of [0, 1]) for (const s of [0, 1, 2]) if (!spawns[t][s]) throw new Error(`map ${id}: missing spawn ${t}/${s}`);
  // pair each item spawn with its mirror image so both sides get the same item sequence
  itemSpawns.forEach((s, i) => {
    s.id = i;
    s.pair = itemSpawns.findIndex((o) => o.tx === w - 1 - s.tx && o.ty === h - 1 - s.ty);
    s.group = Math.min(i, s.pair < 0 ? i : s.pair);
  });
  const width = w * TILE, height = h * TILE;
  const center = { x: width / 2, y: height / 2 };
  for (const t of [0, 1]) for (const s of spawns[t]) s.heading = Math.atan2(center.y - s.y, 0); // face the enemy side
  const zone = Object.assign({ radius0: Math.hypot(width, height) / 2 + 2 }, raw.zone || {});
  return {
    id, name: raw.name, zh: raw.zh, desc: raw.desc, w, h, tile: TILE, width, height, center,
    rows, tiles, spawns, itemSpawns, pads, items: raw.items || ITEM_IDS, zone,
  };
}

export const MAPS = Object.fromEntries(Object.entries(RAW).map(([id, raw]) => [id, build(id, raw)]));
export const MAP_IDS = Object.keys(MAPS);

export const MODES = { '1v1': 1, '2v2': 2, '3v3': 3 };
// Which spawn slots each team size uses (slot 0 is the centre spawn).
export const SPAWN_SLOTS = { 1: [0], 2: [1, 2], 3: [0, 1, 2] };

export function tileCodeAt(map, x, y) {
  const tx = Math.floor(x / TILE), ty = Math.floor(y / TILE);
  if (tx < 0 || ty < 0 || tx >= map.w || ty >= map.h) return TILE_CODE.pit; // off the map = void
  return map.tiles[ty * map.w + tx];
}

/** Plain-data description of a map that is safe to hand to controllers / JSON. */
export function describeMap(map) {
  return {
    id: map.id, name: map.name, zh: map.zh, desc: map.desc,
    w: map.w, h: map.h, tile: map.tile, width: map.width, height: map.height,
    center: { ...map.center },
    rows: map.rows.map((r) => r.replace(/[A-Ca-c*]/g, '.')), // row 0 = north edge
    layout: map.rows.slice(),                               // same, with spawn (A-C / a-c) and item (*) markers
    spawns: map.spawns.map((t) => t.map((s) => ({ x: s.x, y: s.y }))),
    itemSpawns: map.itemSpawns.map((s) => ({ x: s.x, y: s.y })),
    pads: map.pads.map((s) => ({ x: s.x, y: s.y })),
    items: map.items.slice(),
    legend: Object.fromEntries(Object.entries(TILES).map(([id, t]) => [t.ch, id])),
  };
}
